package com.trough.hot;
import android.content.Context;import android.graphics.Canvas;import android.graphics.Paint;import android.os.SystemClock;import android.view.View;
/** Native non-interactive health overlay; authoritative damage stays in physics. */
final class HalfSwordHealthHud extends View {
 private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final float density;
 private boolean recovered;void model(boolean value){recovered=value;}
 private int player=100,foe=100;private boolean opponent;private String playerLabel="YOU 100",foeLabel="FOE —",playerLoss="",foeLoss="";private long playerFlash,foeFlash;
 HalfSwordHealthHud(Context context){super(context);density=getResources().getDisplayMetrics().density;setClickable(false);setFocusable(false);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);setContentDescription("Prototype health. You100. Opponent awaiting physics.");}
 void update(int you,int enemy,boolean present,int outcome){you=Math.max(0,Math.min(100,you));enemy=Math.max(0,Math.min(100,enemy));long now=SystemClock.uptimeMillis();boolean hit=false;if(you<player){playerLoss="−"+(player-you);playerFlash=now+700;hit=true;}else if(you>player)playerFlash=0;if(enemy<foe&&present&&opponent){foeLoss="−"+(foe-enemy);foeFlash=now+700;hit=true;}else if(enemy>foe||!present)foeFlash=0;player=you;foe=enemy;opponent=present;playerLabel="YOU "+player;foeLabel=present?"FOE "+foe:"FOE —";setContentDescription((recovered?"Recovered injury training health. You ":"Prototype health. You ")+player+". "+(present?"Opponent "+foe+".":"Opponent awaiting physics.")+(outcome!=0?" "+HalfSwordRound.label(outcome):""));invalidate();if(hit)postInvalidateDelayed(710);}
 protected void onDraw(Canvas canvas){super.onDraw(canvas);float gap=12*density,w=(getWidth()-gap)*.5f;if(w<=0)return;long now=SystemClock.uptimeMillis();bar(canvas,0,w,player,playerLabel,0xff68dfbf,true,now<playerFlash,playerLoss);bar(canvas,w+gap,w,foe,foeLabel,0xffffbf69,opponent,now<foeFlash,foeLoss);}
 private void bar(Canvas canvas,float x,float width,int health,String label,int color,boolean known,boolean flash,String loss){float y=19*density,h=7*density;paint.setStyle(Paint.Style.FILL);paint.setColor(0xdd122127);canvas.drawRect(x,0,x+width,31*density,paint);paint.setTextSize(11*density);paint.setColor(0xfff0f5f7);paint.setTextAlign(Paint.Align.LEFT);canvas.drawText(label,x+3*density,13*density,paint);if(flash){paint.setColor(0xffff7979);paint.setTextAlign(Paint.Align.RIGHT);canvas.drawText(loss,x+width-3*density,13*density,paint);}paint.setColor(0xff34464d);canvas.drawRect(x+3*density,y,x+width-3*density,y+h,paint);if(known){paint.setColor(flash?0xffff7979:color);canvas.drawRect(x+3*density,y,x+3*density+(width-6*density)*health/100f,y+h,paint);}paint.setTextAlign(Paint.Align.LEFT);}
}
